            padding: 0.5rem 1.2rem;
            background-color: var(--accent-color);
            color: white;
            border-radius: 20px;
            font-weight: 500;
            transition: background 0.3s;
        }

        .btn-search-nav:hover {
            background-color: #e68a00;
        }

        /* Hero Section */
        .hero {
            background: linear-gradient(rgba(0,0,0,0.4), rgba(0,0,0,0.4)), url('https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=1440&q=80');
