        <!-- List -->
        <main class="hotel-list">
            <div class="hotel-card" onclick="window.location.href='details.html'">
                <div class="hotel-image">
                    <div style="width:100%;height:100%;background-image: url('https://images.unsplash.com/photo-1571896349842-33c89424de2d?w=600&q=80');background-size:cover;"></div>
